xstring adjust_capitlization(xstring user_str, xstring full_str)
{
xstring get_full_str = full_str;
xstring get_prt_str = user_str;
xstring correct_str;
int find_my_str;
int length_str = user_str.length();
for(int i = 0; i <= get_full_str.length(); i ++)
get_full_str[i] = toupper(get_full_str[i]);
for(int j = 0; j <= get_prt_str.length(); j ++)
get_prt_str[j] = toupper(get_prt_str[j]);
find_my_str = get_full_str.find(get_prt_str);
if(find_my_str != -1)
correct_str =  full_str(find_my_str,length_str);
else
correct_str = user_str;
return correct_str;
  }

xstring check_add_fields(xstring str_check)
{
xstring my_char = ",";
xstring part_str;
xstring fixed_str;
int length_str;
int my_indication;
my_indication = str_check.find(my_char);
//if there is only one additional field
if(my_indication == -1){
fixed_str = str_check.strip(2);
fixed_str = adjust_capitlization(fixed_str, str_prt_cf_all);
if(is_in_string(fixed_str,str_prt_cf_all) == false)
throw FatalError("ERROR: There is no CF field with the name:  " + fixed_str + ".  All
CF fields:" +
str_prt_cf_all);
}
//more than one additional field
while(my_indication != -1){
length_str = str_check.length();
my_indication = str_check.find(my_char);
part_str = str_check( 0 ,my_indication).strip(2);
str_check = str_check(my_indication + 1,length_str -(my_indication+1) );
part_str = adjust_capitlization(part_str, str_prt_cf_all);
fixed_str = fixed_str + "," + part_str;
fixed_str = fixed_str.strip(2);
if(is_in_string(part_str,str_prt_cf_all) == false)
throw FatalError("ERROR: There is no CF field with the name:  " + part_str + ".  All
CF fields:" +
str_prt_cf_all);
}
  return fixed_str;
}

double covg_units_fct(int time, xstring mthly){
// ADIF Possibility for armotization of CSM for IFRS17
if (time < commence_period_w || time > maturity_period_w)
return 0.0;
double add_mthly = 1.;
// Some of the component are monthly
if (mthly == "Y"){
add_mthly = 12.;
}
if (unit_type_mthd == "surv") // Not in use for ADIF neither for TRAD
return surv(time) * cvgunits_adj_factor * covunit_qne_mida;
else if (unit_type_mthd == "SA"){
//if(time == 0){
//return max(0., sum_at_risk_claim(1))
//* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
//}
//return max(0., sum_at_risk_claim(time))
//* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
return max(0., sum_at_risk_claim(time+1))
* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
}
else if (unit_type_mthd == "reserve")
return reserve(min(max(0.,time),maturity_period_w))
* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
else if (unit_type_mthd == "Premium")
return premium_total(time) *12.
* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
else if (unit_type_mthd == "Tzvira")
// it could be surr_value(t) or units_b(t)
return surr_value(time)
* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
else if (unit_type_mthd == "dmei_nihul_var_fixed") // for 79 < fund < 300
return surr_value(time) * mgt_fee_fixed_col(time)
* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
//return surr_value(time) * monthly_rate(mgt_fee_fixed_col(time))
//* cvgunits_adj_factor / add_mthly;
else if (unit_type_mthd == "dmei_nihul_fixed") // there is no Trad fund = 300
return management_fee(time)
* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
return 0.;
}

