bool is_in_tbl(R row_index ,C col_index , T tbl_name, bool indication)
{
//false - if the row doesn't exist don't do the lookup.
//true - if the row doesn't exist stop the run.
xstring lookup_result;
lookup_result =  tbl_name(row_index , col_index , 1);
if(LOOKUP_FAILED == 0)
return true;
else if(indication == true)
throw FatalError("Error: Row Index: " + xstring(row_index) + " doesn't exist in the table:
" + xstring(tbl_name));
