void set_forward_rates(void)
{
int i = 0.;
int end_loop = spotrates_tbl.no_of_rows()  - 1.;
for (i=1; i <= 120; i++)
{
if( i == 1){
rdr[i] = spotrates_tbl(i , rdr_vector) + int_margin + add_lp;
risk_free_inv[i] = spotrates_tbl(i , invrate_vector) + add_lp;
}
if(i > 1 && i <= end_loop){
if(spotrates_tbl(i , rdr_vector) != 0)
rdr[i] = (pow((1 + spotrates_tbl(i , rdr_vector) + add_lp),i)/pow((1 +
spotrates_tbl(i - 1 , rdr_vector) + add_lp),i - 1)) -1. + int_margin;
else
rdr[i] = rdr[i-1];
if(spotrates_tbl(i  , invrate_vector) != 0)
risk_free_inv[i] = (pow((1 + spotrates_tbl(i  , invrate_vector) + add_lp),i
)/pow((1 + spotrates_tbl(i - 1 , invrate_vector) + add_lp),i - 1)) -1.;
else
risk_free_inv[i] = risk_free_inv[i-1];
}
if(i > end_loop){
rdr[i] = rdr[end_loop];
risk_free_inv[i] = risk_free_inv[end_loop];
}
}
}

