r_num = max(1 , r_num - adjust_back_to_annuity);
decr_back_units_array[r_num] =
1.;//prob_retire_array[r_num];
for(int i=1 ;i < r_num;i++){
decr_back_units_array[r_num - i] = decr_back_units_array[r_num - i + 1.] * (1-
prob_retire_array[r_num - i]);}
}
else
ret_ages_array[1] = max_ret_age;
}

