void validate_data(void) {
if (elapsed_months != 0 && eq(projection_type,"NEW_BUS"))
throw NonFatalError("If New_Bus projection type, then elapsed months must be zero.");
if (prem_term > benefit_term)
throw NonFatalError("__1_");
if (eq(projection_type,"NEW_BUS") && !eq(target_column,"appraisal_value"))
throw NonFatalError("For a new business run, the target must be set to appraisal_value.");
if (pv_period != 12)
throw NonFatalError("Template set up for monthly projections. Change the discount period in
task.");
// check minimum age of mortality tables
//int min_age_1 = death_rates_low_index;
int min_age_1 = 0;
//if (mort_sel_status=="N")
//
min_age_1 = max(0, min_age_1 + death_rates.no_of_columns() - 1);
if (age_exact_issue < min_age_1)
throw NonFatalError("Policy number " + pol_number + " : Issue age of life 1 is less than the
minimum age of the mortality table");
if (eq(projection_type,"VALN") && elapsed_months < 0)
throw NonFatalError("_2__");
if (eq(projection_type,"VALN") && elapsed_months == 0) {
projection_type = "PRICING";
}
if (elapsed_months >= benefit_term)
throw NonFatalError("_3__");
// Ensure frequencies given are factors of 12.
if (cover_status == "PREM_PAY" || prem_term > elapsed_months){
if (prem_freq == 0)
throw NonFatalError("Premium frequency must be 1, 2, 3, 4, 6, or 12.");
// Premium frequency must be a multiple of 12 whilst premiums are being paid
if  (12 % prem_freq != 0)
throw NonFatalError("Premium frequency must be 1, 2, 3, 4, 6, or 12.");
}
if ((12 % dividend_distr_freq != 0.0) || (dividend_distr_freq == 0))
throw NonFatalError("Surplus distribution frequency must be 1, 2, 3, 4, 6, or 12.");
if (cover_status == "PREM_PAY" && prem_curr_total <= 0.0)
throw NonFatalError("_4__");
if (old_adif && cover_status == "PREM_PAY" && saving_prop < alloc_rate[0])
throw NonFatalError("_5__");
if(unit_value_accum + unit_value_savings < SMALL_DOUBLE)
throw NonFatalError("No Accumulation for this policy");
if(prem_curr_if_i * madad_current >=9,999,999.)
throw NonFatalError("Invalid Premium");
//if(elapsed_months < 1)
//
throw NonFatalError("cover _dur < 1");
// close function
}

