<<endl;
return maturity_amt / factor1 / more_imp_factor;
}
else
return maturity_amt /
(gteed1_perc * factor1
+ gteed2_perc * factor2
+ gteed3_perc * factor3
+ gteed4_perc * factor4) / more_imp_factor;
}
// ELiyahu
if(ret_age >= 60 && ret_age <= 70)
