double covg_units_fct(int time, xstring mthly){
double add_mthly = 1.;
// Some of the component are monthly
if (mthly == "Y"){
add_mthly = 12.;
}
// ANNUITY Possibility for armotization of CSM for IFRS17
//if (time <= commence_period_w || time > maturity_period_w)
if (time > maturity_period_w)
return 0.0;
if (unit_type_mthd == "reserve")// fund = 500 & fund == 400 : Bezeq only for Annuity
return reserve_tot(min(max(0.,time),maturity_period_w))
 * cvgunits_adj_factor / add_mthly * covunit_qne_mida;
else if (unit_type_mthd == "SA"){
//if (time == 0){
//return max(0., ann_pay_total_cf(1))
 //* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
//}
//return max(0., ann_pay_total_cf(time))
 //* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
return max(0., ann_pay_total_cf(time+1))
 * cvgunits_adj_factor / add_mthly * covunit_qne_mida;
}
else if (unit_type_mthd == "surv") // Not in use for ADIF neither for TRAD
return surv_all_for_cf(time)
 * cvgunits_adj_factor;
else if (unit_type_mthd == "Premium"){
if (time == 0){
return 0.;
}
return premium_total_cf(time)
 * cvgunits_adj_factor *12. / add_mthly * covunit_qne_mida;
}
else if (unit_type_mthd == "Tzvira") // no for ANNUITY
// it could be surr_value(t) or units_b(t)
return reserve_tot(min(max(0.,time),maturity_period_w))
 * cvgunits_adj_factor / add_mthly * covunit_qne_mida;
else if (unit_type_mthd == "dmei_nihul_var_fixed") // for 79 < fund < 300
return reserve_tot(min(max(0.,time),maturity_period_w))
 * monthly_rate(mgt_fee_fixed_col(time))
 * cvgunits_adj_factor / add_mthly * covunit_qne_mida;
else if (unit_type_mthd == "dmei_nihul_fixed"){ // there is no Trad fund = 300
if (annuity_payment_status == "DEFERRED"){
return reserve_tot(min(max(0.,time),maturity_period_w))
 * monthly_rate(mgt_fee_fixed_col(time))
 * cvgunits_adj_factor / add_mthly * covunit_qne_mida;
}
else{
return reserve_tot(min(max(0.,time),maturity_period_w))
 * monthly_rate(0.01)
 * cvgunits_adj_factor / add_mthly * covunit_qne_mida;
}
}
return 0.;
}

