int split_to_tables(const xstring& Filename,int sp)
{
//When there are no splits
if(sp <= 0) return 0.;
if(file_exist(Filename) == false)
throw FatalError("ERROR: The file:  " + Filename + "
doesn't exist.");
xstring chain; xstring cont; xstring word_skp; xstring wrd_temp;
string s,word,line;
int rows_cnt = -1.; int cells_cnt = 0; int columns_cnt = 0;
int i;int j; int k;
int row_ind = 1.;
int skp_ind = 0.;
int skp_word_ind = 0.;
//count rows with *
ifstream in;
in.open(Filename.c_str());
while(!in.eof()) {
getline(in, s);
if(s.find("*")<=0){
//skip on rows that start with *
word_skp = last_word_str(s);
skp_ind = skp_ind + 1.;
}
rows_cnt =rows_cnt+1;
}
in.close();
rows_cnt = rows_cnt - skp_ind + 1;
//count cells
fstream file;
file.open(Filename.c_str());
//Count table cells
while (file >> word){
wrd_temp = word;
if(skp_ind>0 && skp_word_ind == 0){
//start count from the next word after the last
sentence that starts with *
if(wrd_temp.strip(2) == word_skp)
skp_word_ind = 1.;
}
else
cells_cnt = cells_cnt+1;
}
file.close();
skp_word_ind = 0.;
columns_cnt = cells_cnt/rows_cnt;
//Fill array with table content
SmartArray<xstring> full_tbl_array(cells_cnt + 1, "", "full_tbl_array");
file.open(Filename.c_str());
cells_cnt = 1.;
while (file >> word)
{
wrd_temp = word;
if(skp_ind>0 && skp_word_ind == 0){
//start count from the next word after the last
sentence that starts with *
if(wrd_temp.strip(2) == word_skp)
skp_word_ind = 1.;
}
else{
full_tbl_array[cells_cnt]= word;
cells_cnt = cells_cnt + 1.;
}
}
cells_cnt = cells_cnt - 1.;
file.close();
//multidimentional array that map the table
SmartArray<SmartArray<int>> map_arr(rows_cnt + 1.);//changed from + 1 to + 2
for(j = 0; j <= (rows_cnt) ; j++)
map_arr[j].resize(3);
//strings that define the uniqe key
SmartArray<xstring> keys_array(rows_cnt, "", "keys_array");
SmartArray<xstring> keys_array_2(rows_cnt, "", "keys_array_2");
//string that use for table name
SmartArray<xstring> get_unique(rows_cnt, "", "get_unique");
//Build the uniqe key of table
for(i = 1.;i<=min(columns_cnt,sp); i++){
for(j = 1; j <= (rows_cnt-1) ; j++){
keys_array[j] = full_tbl_array[columns_cnt * j + 1 + (i-1)];
if(i>1) cont = "_";
keys_array_2[j] =keys_array_2[j] + cont + keys_array[j];
}
}
//Define orders and borders
for(j = 1; j <= (rows_cnt-1) ; j++){
//map_arr[j].resize(3);
if(j==1){
map_arr[j][0] = 1.;
get_unique[j] = keys_array_2[j];
}
else{
if(
keys_array_2[j] == keys_array_2[j-1])
map_arr[j][0] = map_arr[j - 1][0];
else{
map_arr[j][0] = map_arr[j - 1][0] + 1;
row_ind = row_ind + 1;
get_unique[row_ind] = keys_array_2[j];
}
}
map_arr[j][1] = j * columns_cnt + 1;
map_arr[j][2] = (j + 1) * columns_cnt;
}
//define number of tables
int max_group = map_arr[rows_cnt-1][0];
j = 1.;
//build the tables
for(k = 1; k<= max_group; k++){
xstring unique_id_prt_tbl;
unique_id_prt_tbl = Filename(0,Filename.find(".")) + "_" + get_unique[k] +".tbl";
ofstream text_file_prt_tbl;
text_file_prt_tbl.open(unique_id_prt_tbl);
for(i=1; i<=columns_cnt ;i++){
if(i == 1 + sp)
text_file_prt_tbl  << full_tbl_array[i];
else if(i > 1 + sp)
text_file_prt_tbl  << " "<< full_tbl_array[i];
}
text_file_prt_tbl << endl;
while(map_arr[j][0] == k){
for(i = map_arr[j][1]; i<=map_arr[j][2];i++){
if(i == map_arr[j][1] + sp)
text_file_prt_tbl  << full_tbl_array[i];
else if(i>map_arr[j][1] + sp)
text_file_prt_tbl  << " "<< full_tbl_array[i];
if( i == map_arr[j][2])
text_file_prt_tbl << endl;
}
j = j + 1;
}
text_file_prt_tbl << endl;
text_file_prt_tbl.close();
}
return sp;
}

double set_datetogil_fromdbase(double dbase, double dpurp){
// when the date are in format yyyymm
// The purpose is to return the age at the Output date for policy !
double gil = 0.;
// Year difference
int year_dpurp = xint(dpurp / 100.);
int year_dbase = xint(dbase / 100.);
int diff_year = year_dpurp - year_dbase;
// Month difference
int month_dpurp = dpurp - year_dpurp * 100.;
int month_dbase = dbase - year_dbase * 100.;
int diff_month = month_dpurp - month_dbase;
gil = max(0., diff_year + diff_month / 12.);
//log_strm << "dpurp" << " = " << dbase << " dpurp" << " = " << dpurp << " gil" << " = " <<
gil << endl;
return gil;
}

