return 0.;
if(inlist(adif->qod_chgsts,"BT,PR,PD"))
if(t== t_bt) return 1.;
else return 0;
}
double rate = adif->lapse_rate_array_pup[xint(adif->pol_year(t))] * adif-
>lapse_mult_array_pup[xint(adif->cal_year(t) - 2020)];
if ((t <= adif->year_scenario_start * 12 )&&(adif->lapse_mult_solvency != 1.)&&(adif-
>lapse_mult_solvency > SMALL_DOUBLE)){
rate = rate / adif->lapse_mult_solvency;
}
return 1. - pow((1. - rate), 1./12.);

if (unit_type == "fund_pup")
return 0;
// from here is only for PP
if( (t >= adif->t_decrease_prem && adif->hoz_hashqa != "Y") || (t >= adif->t_decrease_prem && adif-
>age_above_80 != "Y") ) //new
return monthly_rate( adif-> rates_stop_premium_in_retirment); //new
if (t+elapsed_months >= adif->prem_term && t+elapsed_months < adif->benefit_term)
return 1.;
int t_bt =
adif->ev_time_n/2 + 1.;
if(fc_lapse==1||fc_claims==1||fc_hatavot==1||fc_amalot==1 ){
// this can only happen if fund_pp
if(inlist(adif->qod_chgsts,"PP_PP,BT,PR,PD,PP_PP_GM,PUP_PP_GM,PUP_PUP_GM") && t<=
adif->ev_time_n)
return 0.;
if(inlist(adif->qod_chgsts,"PP_PUP,PP_PUP_GM"))
if(t == t_bt) return 1.;
}
if (adif->lapse_total(t) == 1.)  // lapse policy if premium for riders higher than total premium
(i.e. not enough premium)
return 1.;
double pup_prop = adif->pup_proportion_arr[xint(adif->pol_year(t))];
if (adif->pigur_switch == "Y" && adif->qod_pigur == "Y" && adif->cover_status == "PREM_PAY")
if (t<=12) pup_prop = adif->pigur_puppct;
return adif->lapse_total_for_pup(t) * pup_prop;
//return adif->lapse_total(t) * adif->pup_proportion;
// old code
//return adif->lapse_total(t) * adif->pup_proportion_arr[xint(adif->pol_year(t))];

//if (t <= commence_period_w || t > maturity_period_w)
if (t <= 0 || t > maturity_period_w)
return 0.0;
double pid_nid_factor = 1.;
int prem_pay_period = 1;
int time_since_pup = 1;
double dbl_dur = elapsed_months;
double dbl_t = t;
int t_bt = adif->ev_time_n/2 + 1.;
svafterpup_tbl = adif->rafm_input_parameters + "\\MISC\\" + "svafterpup.tbl";
if(adif->prod_class == "ADIF5")
// only relevant for ADIF5
{
if(adif->cover_status == "PREM_PAY")
{
if (unit_type == "fund_pp")
time_since_pup = 1;
else
// new pup from the prem_pay policy
time_since_pup = 10; // conservative - gets more SV
(need to consider
how to model new pup's better)
prem_pay_period = min((dbl_dur + dbl_t - 1.)/12., 10.);
}
else // PUP policy
{
prem_pay_period = min(dbl_dur/12.,10.); // assumes stopped paying at start of
projection
time_since_pup = min(dbl_t / 12., 10.);
}
pid_nid_factor = atof(svafterpup_tbl(adif->men_prat + "_" + xstring(time_since_pup),
prem_pay_period));
}
if((fc_lapse==1||fc_claims==1||fc_hatavot==1|| fc_amalot==1 )&& inlist(adif-
>qod_chgsts,"BT,PR,PD,TS") && t == t_bt)
return units_e_bef(t);
if((fc_claims==1||fc_hatavot==1||fc_amalot==1)&& inlist(adif->qod_chgsts,"DT") && t>= t_bt)
return 0.;
if( ( t >= adif->t_zero_lapse && adif->hoz_hashqa != "Y") || ( t >= adif->t_zero_lapse && adif-
>age_above_80 != "Y") )
return 0.0;
return surr_value(t-1) * (min(1.,lapse_rate(t) + withd_rate(t))) * pid_nid_factor;
double pre_surr_value = units_b(t) + int_cred_units_e(t)
- management_fee(t) -
claims_maturity_honi(t)
- claims_maturity_tur(t) - claims_death_units(t) + premium_single(t);
//calculate surrender at end-of-period without circular reference to surr_value, net
of surr_charge
return pre_surr_value * (min(1.,lapse_rate(t) + withd_rate(t))) * pid_nid_factor;

if (t <= commence_period_w || t > maturity_period_w)
return 0.0;
//if (pup_sv_rebate_w == "Y")  // penalty not incurred when policies become paid-up, only when
surrendered
return surr_penalty_e_bef(t) * lapse_rate(t);
//else
//
return surr_penalty_e_bef(t) * (lapse_rate(t) + pup_rate(t));

if (t <= commence_period_w || t > maturity_period_w)
return 0.0;
// The surrender penalty is calculated before
// surrender claims have been paid but after death claims
double surr_penalty = 0.0;
// full penalty for prem-paying units
if (unit_type == "fund_pp")
surr_penalty = (units_e_bef(t) - claims_death_units(t))
* basic_prop_units_b(t) * adif->surr_chg_perc_units[xint(adif-
>pol_year(t))];
// If there is no PUP SV rebate, then paid-up units have already been reduced by the charge when
the units became paid-up.
if (unit_type == "fund_pup" && pup_sv_rebate_w == "N")
surr_penalty = 0.;
// calculate surrender penalty after rebate for paid-up, when there is a rebate
// currently pup_sv_rebate_w = N always (but ADIF 5 is done in surrender claims)
if (unit_type == "fund_pup" && pup_sv_rebate_w == "Y")
for (int i = 1; i<=t; i++)  {// i is projection month when policy became paid up
xstring row = adif->men_prat + "_" + xstring(min(10 , int((t-i)/12.)));
xstring col = xstring(min(10 , adif->pol_year(i)));
surr_penalty = surr_penalty
+ units_b_bef_pup_bas(i)
// new paid up units at time i
* (1. - adif->surr_value_rebate_tbl(row , col))
// SV
penalty at time t for units that became paid up at time i
* advance_factor(t) / advance_factor(i);
// adjustment for
interest and survival
//
surr_penalty = surr_penalty
//
+ units_b_bef_pup_bas(i) * sv_pup_factor_tbl(adif->pol_year(i)
, xint((t-i)/12.))
//
* advance_factor(t) / advance_factor(i);
}
// limit the maximum surrender penalty to the nominal value of the units
return min(surr_penalty, units_e_bef(t));

if (t <= commence_period_w || t > maturity_period_w)
return 0.0;
return units_e(t);

if (t <= commence_period_w || t > maturity_period_w)
return 0.0;
double porp_units =  units_b_bef(t)/(adif->units_b_bef(t));
int i;
int length = adif->dyn_comm_tbl.no_of_rows();
double comm_rate =  adif->comm_acc;
if(adif->prod_class == "MOR_PREMIUM_2020"){
for(int i = 1; i <= length; i++){
 if(units_b_bef(t) <= surv(t) * (adif->dyn_comm_tbl(i,"TZVIRA"))){
comm_rate = adif->dyn_comm_tbl(i,"COMM_RATE")/(1. + adif->vat_arr[max(0,
adif->cal_year(t) - adif->valn_year)]);
break;}
}
}
// % of unit reserve commission are assumed to be payable monthly at the beginning of month
return units_b_bef(t) * (1. + adif->vat_arr[max(0, adif->cal_year(t) - adif->valn_year)]) *
comm_rate / 12.;

if (t <= commence_period_w || t > maturity_period_w)
return 0.0;
return units_b(t) * adif->investment_return(t);

