return benefits_curr * surv(t);

if (t <= commence_period_w || t > maturity_period_w)
return 0.0;
return units_b_bef(t) + alloc_units(t) ;

if (t <= commence_period_w || t > maturity_period_w)
return 0.0;
double new_pup = 0.0;
if (unit_type == "fund_pup")
new_pup = units_b_bef_pup(t) - units_b_bef_pup_bas_pen(t);
else // deduction from premium paying units//
new_pup = - units_b_bef_pup(t);
if (t == 1)
return units_e(t-1) - claims_maturity_honi(t-1) - claims_maturity_tur(t-1) + new_pup;
//TM - correcting for policies with maturity at t=0 to take opening amount and reduce
by maturities since units_e(t-1) in this case is just the opening amount//
else
