return
units_b(t)
+ int_cred_units_e(t)
- management_fee(t)
- claims_maturity_honi(t)
- claims_maturity_tur(t)
- claims_death_units(t)
- claims_surrender(t)
- surr_charge(t)
+ premium_single(t);

if (t <= commence_period_w || t > maturity_period_w)
return 0.0;
if (t==0)
return units_e(t);
return
units_b(t)
+ int_cred_units_e(t)
- management_fee(t)
- claims_maturity_honi_bef(t)
- claims_maturity_tur_bef(t);

