if(eq(after_tax_ev,"Y"))
return dividend_pretax(t) * tax_rates[max(0 , xint(cal_year(t)) - valn_year)];
return 0.0;

//if (t < commence_period_w || t >=  maturity_period_w)
if (t < 0 || t >=maturity_period_w)
return 0.0;
//Correcting discount timing from v_month(t) to v_month(t+1) so Res - BEL = VIF
return v_month(t+1) *(tax_pv(t+1) + tax(t+1));

//if (t < commence_period_w || t >=  maturity_period_w)
if (t < 0 || t >=maturity_period_w)
return 0.0;
return v_month_trad(t) *(tax_pv_trad(t+1) + tax(t+1));

int temp_t = 0;
//int ev_time_adj = 0;
//
//if(chgev_run > 0.)
//ev_time_adj = ev_time_n;
//
//temp_t = max((t - 1 - ev_time_adj),1)/12. + 1;
temp_t = max((t - 1 - interest_shift),1)/12. + 1;
if (t > maturity_period_w)
return 0.0;
if (model_basis_w == "RESERVE")
return 1./(1. + int_rate_res_monthly);
return pow(1. + rdr[temp_t], -1./12.);

int temp_t = 0;
//int ev_time_adj = 0;
//
//if(chgev_run > 0.)
//ev_time_adj = ev_time_n;
//
//temp_t = max((t - 1 - ev_time_adj),1)/12. + 1;
temp_t = max((t - 1 - interest_shift),1)/12. + 1;
if (use_fixed_rate == "Y")
return  pow(1. + int_margin_trad, -1./12.);
else
return  pow(1. + rdr[temp_t] - int_margin + int_margin_trad, -1./12.);

// In order to have a comparaison for every month
if (t < 0 || t > maturity_period_w)
return NO_AVG;
double sa_temp = 0.;
if (t == 0){
if(sum_insured_mthly > SMALL_DOUBLE)
sa_temp = sum_insured_mthly;
else if (fixed_loss_ratio_approach == "Y")
sa_temp = data_prem;
else if (fixed_claim_approach == "Y")
sa_temp = fixed_claim * 12.;
else
sa_temp = claims_cost_array_w[xint(age_exact_1(1))] * madad_current /
madad_claims_cost_base;
return count_trf * sa_temp;
}
if(sum_insured_mthly > SMALL_DOUBLE)
sa_temp = sum_insured_mthly * surv_healthy (t);
else if (fixed_loss_ratio_approach == "Y")
sa_temp = (premium_reg_healthy(t) + premium_extra(t) - premium_discount(t)) * 12.;
else if (fixed_claim_approach == "Y")
sa_temp = fixed_claim * surv_healthy(t) * 12.;
else
sa_temp = surv_healthy(t) * claims_cost_array_w[xint(age_exact_1(max(1,t)))] * madad_current
/ madad_claims_cost_base;
return count_trf * sa_temp;

if (t < 0 || t >= maturity_period_w)
return 0.0;
double temp;
temp = embedded_value_e(t);
return max(0.,temp);

