template <class T >
xstring multi_index_lookup(xstring tbl_look_ind , xstring tbl_headers_ind , T tbl_name , xstring
col_lookup)
{
tbl_look_ind = tbl_look_ind.strip(2);
tbl_headers_ind = tbl_headers_ind.strip(2);
col_lookup = xstring(col_lookup).strip(2);
xstring my_char = ",";
xstring prt_header;
xstring prt_look;
xstring i_str;
int length_str_headers;
int length_str_look;
int my_indication = 0.;
int my_indication_look = 0.;
int check1 = 0.;
int final_row = 0.;
int col_ind = 0.;
int i = 0.;
int j = 0.;
int tbl_rows = tbl_name.no_of_rows();
SmartArray <int> mult_array(tbl_rows+1, 1);
SmartArray <SmartArray <double>> my_two_dim_array(100);
//more than one additional field
while(my_indication != -1){
//select any header lookup
length_str_headers = tbl_headers_ind.length();
my_indication = tbl_headers_ind.find(my_char);
prt_header = tbl_headers_ind( 0 ,my_indication).strip(2);
tbl_headers_ind = tbl_headers_ind (my_indication + 1 , length_str_headers -
(my_indication+1));
//select any value that we look after
length_str_look = tbl_look_ind.length();
my_indication_look = tbl_look_ind.find(my_char);
prt_look = tbl_look_ind( 0 ,my_indication_look).strip(2);
tbl_look_ind = tbl_look_ind (my_indication_look + 1 , length_str_headers -
(my_indication_look + 1));
col_ind = col_ind + 1.;
my_two_dim_array[col_ind].resize(tbl_rows + 1);
for(i = 1. ; i <= tbl_rows; i++){
i_str = i;
if(prt_look == tbl_name(i_str,prt_header).strip(2))
my_two_dim_array[col_ind][i] = 1.;
}
}
if(col_ind > 1)
for(j = 1. ; j <= col_ind-1; j++){
for(i = 1. ; i <= tbl_rows; i++){
mult_array[i] =  mult_array[i] * (my_two_dim_array[j][i] *
my_two_dim_array[j+1][i]);
}
}
else
for(i = 1. ; i <= tbl_rows; i++)
mult_array[i] =  mult_array[i] * my_two_dim_array[col_ind][i] ;
//check there is only one lookup in the table:
for(i = 1. ; i <= tbl_rows; i++){
if(mult_array[i]>0)
check1 = check1 + 1;
}
if(check1 == 0)
throw NonFatalError(product_rafm + " there is no match for this index in the table:
  " +
tbl_name);
if(check1 > 1)
throw NonFatalError(product_rafm + " there is more than one option for this multi_lookup in
the table:
  " + tbl_name);
for(i = 1. ; i <= tbl_rows; i++)
final_row = final_row + mult_array[i]*i;
if(eq(col_lookup,""))
return xstring(final_row);
i_str = final_row;
return tbl_name(i_str,col_lookup).strip(2);
}

double ra_ifrs17_fct(int time, xstring mthly, xstring grossnetreins){
// Components of RiskAdjustment
if (time <= commence_period_w || time >= maturity_period_w || time < 0 )
return 0.0;
double mortality_driver = 0.;
double longevity_driver = 0.;
double longevity_tur_driver = 0.;
double disability_driver = 0.;
double lapse_driver = 0.;
double expense_driver = 0.;
double cat_driver = 0.;
double oprisk_driver = 0.;
if (grossnetreins == "gross"){
mortality_driver = set_ra_driver_component(mortality_driver_gross, time, mthly);
longevity_driver = set_ra_driver_component(longevity_driver_gross, time, mthly);
longevity_tur_driver = set_ra_driver_component(longevity_tur_driver_gross, time,
mthly);
disability_driver = set_ra_driver_component(disability_driver_gross, time, mthly);
if (pvfp_lapse_runoff(0)>0.){
lapse_driver = set_ra_driver_component(lapse_driver_gross, time, mthly);
}
expense_driver = set_ra_driver_component(expense_driver_gross, time, mthly);
cat_driver = set_ra_driver_component(cat_driver_gross, time, mthly);
oprisk_driver = set_ra_driver_component(oprisk_driver_gross, time, mthly);
// Risk Adjustment GROSS total calcul
return ra_factor * (mortality_driver * mortality_factor_gross
+ longevity_driver * longevity_factor_gross
+ longevity_tur_driver * longevity_tur_factor_gross
+ disability_driver * disability_factor_gross
+ lapse_driver * lapse_factor_gross
+ expense_driver * expense_factor_gross
+ cat_driver * cat_factor_gross
+ oprisk_driver * oprisk_factor_gross );
}else if (grossnetreins == "rein"){
mortality_driver = set_ra_driver_component(mortality_driver_rein, time, mthly);
longevity_driver = set_ra_driver_component(longevity_driver_rein, time, mthly);
longevity_tur_driver = set_ra_driver_component(longevity_tur_driver_rein, time,
mthly);
disability_driver = set_ra_driver_component(disability_driver_rein, time, mthly);
if (pvfp_lapse_runoff(0)>0.){
lapse_driver = set_ra_driver_component(lapse_driver_rein, time, mthly);
}
expense_driver = set_ra_driver_component(expense_driver_rein, time, mthly);
cat_driver = set_ra_driver_component(cat_driver_rein, time, mthly);
oprisk_driver = set_ra_driver_component(oprisk_driver_rein, time, mthly);
// Risk Adjustment NET total calcul
return ra_factor * (mortality_driver * mortality_factor_rein
+ longevity_driver * longevity_factor_rein
+ longevity_tur_driver * longevity_tur_factor_rein
+ disability_driver * disability_factor_rein
+ lapse_driver * lapse_factor_rein
+ expense_driver * expense_factor_rein
+ cat_driver * cat_factor_rein
+ oprisk_driver * oprisk_factor_rein );
}
return 0.;
}

template <class R, class W >
void replace_var_value(R rep,W with)
{
int k;
//put double into double, or integer into double, or integer into integer:
if((Variable(rep).GetType() == 0 && Variable(with).GetType() == 0 )
|| (Variable(rep).GetType() == 1 && Variable(with).GetType() == 0 )
|| (Variable(rep).GetType() == 1 && Variable(with).GetType() == 1))
 Variable(rep).SetValue(Variable(with).Value());
//replace string variable
else if(Variable(rep).GetType() == 2 && Variable(with).GetType() == 2 )
 Variable(rep).SetValue(Variable(with).ValueAsString());
//replace arrays: put integer into double, or integer into integer:
else if((Variable(rep).GetType() == 4 && Variable(with).GetType() == 4 )
|| (Variable(rep).GetType() == 5 && Variable(with).GetType() == 4 )){
for(k = 0; k<=Variable(rep).size() - 1;k++)
Variable(rep).SetElementValue(k,Variable(with).elementValueAsInt(k));}
//replace arrays: put double into double
else if(Variable(rep).GetType() == 5 && Variable(with).GetType() == 5){
for(k = 0; k<=Variable(rep).size() - 1;k++)
Variable(rep).SetElementValue(k,Variable(with).elementValueAsDouble(k));}
else
throw FatalError("ERROR: The variable
" + Variable(rep).Name() +" and the variable
" + Variable(with).Name()  + "  are not the same type");
}

