void validate_data(void) {
if (pv_period != 12)
throw FatalError("Application is set up for monthly projections. Change the discount period
in the projection task.");
// Ensure frequencies given are factors of 12.
if ((12 % prem_freq != 0.0) ||
(prem_freq == 0) || (prem_freq == 0 && prem_term > elapsed_months)) { // premium frequency
must be a multiple of 12 and must
   // not be zero whilst premiums are being paid.
write_msg(SKIP, "Premium frequency must be 1, 2, 3, 4, 6, or 12.");
}
if ((12 % surplus_distr_freq != 0.0) || (surplus_distr_freq == 0)){
write_msg(SKIP, "Surplus distribution frequency must be 1, 2, 3, 4, 6, or 12.");
}
//if (prem_term < 2 && policy_status == "PREM_PAY")
//
write_msg(SKIP, "prem_term too low for premium paying policy ");
if (benefit_term <= elapsed_months && policy_status != "CLAIM")
write_msg(SKIP, "benefit_term <= elapsed_months");
// close function
}

void write_msg(int type, xstring msg) {
//Make the policy number and group fields 10 and 20 characters respectively.
xstring mypolnum = pol_number;
mypolnum.resize(10);
xstring mygroup = group;
mygroup.resize(20);
xstring prefix = pol_number + " - " + mygroup + " - ";
if (type == SKIP) {
//MoSes V4.3 will automatically prefix with "Point skipped: "
xstring message = prefix + msg;
throw NonFatalError(message);
}
if (type == LOG) {
//same length...  "Point skipped: "
xstring message = "Policy valued: " + prefix + msg;
log_strm << message << endl;
}
return; //keep compiler happy
} //close function

