xstring changes_steps = run_parameters_tbl("qod_chg_analysis" , "value");
//The only possible change are death,claim,lapse/PUP
if(is_not_in_string("DT",changes_steps)
&& is_not_in_string("CL",changes_steps)
&& is_not_in_string("BT",changes_steps))
return;
//Define current status
xstring base_sts;
if(cover_status == "PREM_PAY")
base_sts = "PP";
if(cover_status == "PUP")
base_sts = "PUP";
if(cover_status == "CLAIM")
base_sts = "CL";
actual_sts_chg = 1.;
cvr_sts_orig = cover_status;
