double exact_age(int birth_date, int year_start, int month_start) {
int year_birth = xint(birth_date / 10000.);
int month_birth = xint(birth_date / 100.) - year_birth * 100.;
int day_birth = birth_date - xint(birth_date / 100.) * 100.;
int diff_year = year_start - year_birth;
int diff_month = month_start - month_birth;
int diff_day = 1. - day_birth;
double age = 0.;
if((diff_month == 6. && diff_day == 0.) || (diff_month == 7. && diff_day == -30.))
age = diff_year + 0.49;
else if(diff_month == -5. && diff_day == -30.)
age = diff_year - 1. + 0.49;
else
age = (diff_year * 365.25 + diff_month * 30.5 + diff_day) / 365.25;
return age;
}

