void set_cf_parameters(void){
str_prt_cf = "";
str_prt_cf_all = "Prem, PremCF, Prem_Before_Disc, taxes, dividend, BEL_CF_gross"; //
Premium, div, BELgross & taxes
str_prt_cf_all = str_prt_cf_all + ", Reserve, ResInc, Res_np, Res_def, InvInc, hetz_addinv";
// Reserve & Investment
str_prt_cf_all = str_prt_cf_all + ", CommPrem, CommAss, CommDN, mgtfee_prem, mgtfee_tzvira,
expenses, tefahot"; // Commission, (mangementfee for Adif & Trad) & expenses (tefahot for TERM)
str_prt_cf_all = str_prt_cf_all + ", claims_death, claims_death_sv, claims_death_si,
claims_disab, claims_surrender, claims_maturity, claims_annuity"; // Claims
str_prt_cf_all = str_prt_cf_all + ", Prem_re, Comm_re, profcomm, recost, Res_Rein,
BEL_CF_rein, claims_death_si_re, claims_disab_re, Guar_int_re"; // Reinsurance
str_prt_cf_all = str_prt_cf_all + ", PremSavings, prem_current, prem_future, claims_NDIC,
claims_non_NDIC, claims_disab_LIC, claims_disab_LRC, claims_disab_LIC_re, claims_disab_LRC_re";
//IFRS 17
str_prt_cf_all = str_prt_cf_all + ", surv, SA, RA_gross, RA_rein, RA_net, CovgUnits,
CovgUnits_re"; //IFRS 17
str_prt_cf_all = str_prt_cf_all + ", dlr_claim, dlr_rein";//Add fields of dlr (for PHI &
LTC)
str_prt_cf_all = str_prt_cf_all + ", sapakim_exp, sapakim_exp_rein, PVExp_sapakim,
PVExp_sapak_rein";  //Add fields of SAPAKIM_EXP
(for PHI & LTC)
str_prt_cf_all = str_prt_cf_all + ", PVClaims, PVExpenses, PVFP, PVAnnResSP, PVPremium"; //
PV component (PVAnnResSP only annuity)
str_prt_cf_all = str_prt_cf_all + ", NewClaims, CLaimsFactor, expenses_claims,"; // New
xstring str_prt_temporary = str_prt_cf_all;
if(full_cf_prt == "Y") {
str_prt_cf = str_prt_cf_all;
return;
}
xstring NameExtracted = "";
xstring NameExtracted_YN = "";
int dot = 0;
int length = str_prt_temporary.length();
while( length > 1 ){
dot = str_prt_temporary.find(",");
NameExtracted = str_prt_temporary.substr(0, dot);
str_prt_temporary = str_prt_temporary.substr(dot+1,length);
length = str_prt_temporary.length();
if(full_cf_prt == "Y"){
NameExtracted_YN = cf_control(NameExtracted,"FULL_CF");
if(NameExtracted_YN == "Y" && is_in_string(NameExtracted,str_prt_cf)!=true){
str_prt_cf = str_prt_cf + NameExtracted + ",";
}
}else{
if(bel_cf_prt == "Y"){
NameExtracted_YN = cf_control(NameExtracted,"BEL_CF");
if(NameExtracted_YN == "Y" &&
is_in_string(NameExtracted,str_prt_cf)!=true){
str_prt_cf = str_prt_cf + NameExtracted + ",";
}
}
if(solvencycf_prt == "Y"){
NameExtracted_YN = cf_control(NameExtracted,"SOLVENCY_CF");
if(NameExtracted_YN == "Y" &&
is_in_string(NameExtracted,str_prt_cf)!=true){
str_prt_cf = str_prt_cf + NameExtracted + ",";
}
}
if(ifrscf_prt == "Y"){
NameExtracted_YN = cf_control(NameExtracted,"IFRS17_CF");
if(NameExtracted_YN == "Y" &&
is_in_string(NameExtracted,str_prt_cf)!=true){
str_prt_cf = str_prt_cf + NameExtracted + ",";
}
}
if(driver_cf_prt == "Y"){
NameExtracted_YN = cf_control(NameExtracted,"DRIVER_CF");
if(NameExtracted_YN == "Y" &&
is_in_string(NameExtracted,str_prt_cf)!=true){
str_prt_cf = str_prt_cf + NameExtracted + ",";
}
}
if(clientvcf_prt == "Y"){
NameExtracted_YN = cf_control(NameExtracted,"ClientV_CF");
if(NameExtracted_YN == "Y" &&
is_in_string(NameExtracted,str_prt_cf)!=true){
str_prt_cf = str_prt_cf + NameExtracted + ",";
}
}
if(vif_prt == "Y"){
NameExtracted_YN = cf_control(NameExtracted,"VIF_CF");
if(NameExtracted_YN == "Y" &&
is_in_string(NameExtracted,str_prt_cf)!=true){
str_prt_cf = str_prt_cf + NameExtracted + ",";
}
}
if(profcomm_cf_prt == "Y"){
if(is_in_string("profcomm",str_prt_cf)!=true){
str_prt_cf = str_prt_cf + "profcomm" + ",";
}
}
}
if(full_cf_prt != "Y"){
add_cf_field = add_cf_field.strip(2);
if(add_cf_field.length() > 1){
cash_flow_run = "Y";
//check if the fields correct and order them
add_cf_field = check_add_fields(add_cf_field);
}else{
add_cf_field = "";
}
str_prt_cf = str_prt_cf + add_cf_field + ",";
}
// For Test
//log_strm << "dot = " << dot << endl;
//log_strm << "NameExtracted = " << NameExtracted << endl;
