//log_strm << "str_prt_cf = " << str_prt_cf << endl;
//log_strm << "str_prt_temporary = " << str_prt_temporary << endl;
//log_strm << "length = " << length << endl;
}
}

void set_forward_rates(void)
{
int i = 0.;
int end_loop = spotrates_tbl.no_of_rows()  - 1.;
for (i=1; i <= 120; i++)
// calculating forward rates based on the spot rate table
{
if(i == 1){ //On year1 forwards_rate and spot_rate are equal
rdr[i] = spotrates_tbl(i , rdr_vector) + int_margin + add_lp;
risk_free_inv[i] = spotrates_tbl(i , invrate_vector) + add_lp;
rdr_ccf[i] = spotrates_tbl(i, rdr_vector_ccf) + int_margin + add_lp;
}
if(i > 1 && i <= end_loop){
if(spotrates_tbl(i  , rdr_vector) != 0)
rdr[i] = (pow((1 + spotrates_tbl(i , rdr_vector) + add_lp),i )/pow((1 +
spotrates_tbl(i - 1 , rdr_vector) + add_lp),i - 1)) -1. + int_margin;
else
rdr[i] = rdr[i - 1];
if(spotrates_tbl(i  , invrate_vector) != 0)
risk_free_inv[i] = (pow((1 + spotrates_tbl(i, invrate_vector) +
add_lp),i)/pow((1 + spotrates_tbl(i - 1 , invrate_vector) + add_lp),i - 1 )) -1.;
else
risk_free_inv[i] = risk_free_inv[i - 1];
if(spotrates_tbl(i  , rdr_vector_ccf) != 0)
rdr_ccf[i] = (pow((1 + spotrates_tbl(i , rdr_vector_ccf) + add_lp),i)/pow((1
+ spotrates_tbl(i - 1 , rdr_vector_ccf) + add_lp),i - 1)) -1. + int_margin;
else
rdr_ccf[i] = rdr_ccf[i - 1];
}
if(i > end_loop){
rdr[i] = rdr[end_loop];
risk_free_inv[i] = risk_free_inv[end_loop];
rdr_ccf[i] = rdr_ccf[end_loop];
}
}
}

void set_forward_rates_ccf(xstring dyn_rdr_vector_ccf)
{
int i = 0.;
int end_loop = spotrates_tbl.no_of_rows()  - 1.;
rdr_ccf[0] = spotrates_tbl(1, dyn_rdr_vector_ccf) + add_lp + int_margin;
for (i=1; i <= 120; i++){
// calculating forward rates based on the spot rate table
if(i >= 1 && i <= end_loop){
if(spotrates_tbl(i , dyn_rdr_vector_ccf) != 0)
rdr_ccf[i] = (pow((1 + spotrates_tbl(i+1   , dyn_rdr_vector_ccf) +
add_lp),i+1 )/pow((1 + spotrates_tbl(i, dyn_rdr_vector_ccf) + add_lp),i)) -1. + int_margin;
else
rdr_ccf[i] = rdr_ccf[i - 1];
}
if(i > end_loop)
rdr_ccf[i] = rdr_ccf[end_loop];
}
}

