pol_year_np = 0;
double age_exact_issue_np = age_exact_issue;
if (fixed_yrt=="YRT")
age_exact_issue_np = 65;
//Annual calculation - survival & incidence rates
for (i=1;i<=(min(100,claim_end_age_EL) - age_exact_issue_np)*12.; i++) {
if (fmod(i-1., 12.) == 0)
pol_year_np = pol_year_np + 1;
else
pol_year_np = pol_year_np;
