claim_term)) * (1 + period_guar_60) + death_guar_60;
temp_fac = claims_factors_tbl(age_look , heading+xstring(deferred_period_w +
item_claim_term)) * (1 + period_guar_60) + death_guar_60;
temp_fac = temp_fac - claims_factors_tbl(age_look ,
heading+xstring(deferred_period_w)) * (1 + period_guar_36) - death_guar_36;
}
else {
if(wl_ind == "N"){ // not WL
//temp_fac = claims_factors_tbl(age_look , heading+xstring(claim_term));
temp_fac = claims_factors_tbl(age_look , heading+xstring(item_claim_term));
