temp_fac = temp_fac * (1 + period_guar_60) + death_guar_60;
}
}
else
// whole life
temp_fac = claims_factors_tbl(age_look , heading+"WL") * (1 + period_guar_wl)
+ death_guar_wl;
if (deferred_period_w == 60)
// 5 year mashlim (whole life)
temp_fac = temp_fac - claims_factors_tbl(age_look , heading+"60") * (1 +
period_guar_60) - death_guar_60;
if (deferred_period_w == 36)
// 3 year mashlim (whole life)
temp_fac = temp_fac - claims_factors_tbl(age_look , heading+"36") * (1 +
period_guar_36) - death_guar_36;
}
//incidence rates
xstring col_lookup; // for both incidence table and incidence selection table
col_lookup = xstring(morbidity_version) + "_" + incidence_selection_set + "_" +
xstring(min(xint(pol_year_np + (age_exact_issue_np - age_exact_issue)),10));
double incidence_selection_multiplier = 1.;
incidence_selection_multiplier =
incidence_selection_tbl(xint(age_exact_issue_np),col_lookup);
uw_load = (1. + underwriting_load);
xstring long_other = "OTHER";
if(is_in_string("LONG",prod_class)){
long_other = "LONG";
}
//col_lookup = sex + "_" + xstring(adl);
col_lookup = sex + "_" + xstring(adl) + "_" + long_other;
double test_look =  incidence_tbl(-1, col_lookup,1);
if (LOOKUP_FAILED != 0) // lookup failed
col_lookup = sex + "_" + xstring(adl);
sick_rate_yrly_np = incidence_selection_multiplier * incidence_multiplier * uw_load *
incidence_tbl(age_look, col_lookup);
sick_rate_np = 1. - pow(1. - sick_rate_yrly_np, 1./12.);
//death_rate
if (xint(age_look) >= 120)
rate = 1.0;
rate = mort_mult * mort_rates_actives(xint(age_look), sex);
if(selection_tbl_name != "NONE")
if (mort_sel_status == "Y" && (pol_year_np + (age_exact_issue_np -
age_exact_issue)) <= 5) // selection table by entry age
rate = rate * mort_select_tbl(xint(age_exact_issue_np) ,
sex+"_"+xstring(pol_year_np+(age_exact_issue_np - age_exact_issue))); //annually
death_rate_yrly_np = max(0.0, min(1.0, rate));
death_rate_np = 1. - pow(1. - death_rate_yrly_np, 1./12.); // monthly
death_rate_np_dep = death_rate_np * (1. - 0.5 * sick_rate_np);
sick_rate_np_dep = sick_rate_np * (1. - 0.5 * death_rate_np);
if  (i == 1)
surv_per_np = 1;
else
surv_per_np = surv_per_np * (1. - death_rate_np_dep - sick_rate_np_dep);
//premium reinsurance
double premium_re = 0.;
if(ceded_pct > SMALL_DOUBLE){
double prem_load = 0.;
int test_look = atoi(prem_load_tbl(xstring(taarif), "ahuz_hamasa",1));
if(LOOKUP_FAILED != 2)  // found index
prem_load = atof(prem_load_tbl(xstring(taarif), "ahuz_hamasa"));
xstring benefit_payment_per;
double reins_rate_base = 0.; double reins_rate = 0.;
double normalization_factor = 12. * atof(reins_prem_tbl(re_qx_key,
"FRF_QNE_MIDA_SXUM_BITUAH"));
//if (claim_term <= 24)
//benefit_payment_per = "24";
//else
//if (claim_term <= 36)
//benefit_payment_per = "36";
//else
//if (claim_term <= 48)
//benefit_payment_per = "48";
//else
//if (claim_term <= 60)
//benefit_payment_per = "60";
//else
//benefit_payment_per = "WL";
//
//col_lookup = sex + "_" + benefit_payment_per;
if (re_qx_key.length() > 21) // If the "re_qx_key" is complete (length = 29)
reins_rate_base = atof(reins_prem_tbl(re_qx_key, age_look));
reins_rate = reins_rate_base;
//if (deferred_period_w == 60 || deferred_period_w == 36) {
// 3 or 5 year
mashlim (whole life)
//col_lookup = sex + "_" + xstring(deferred_period_w);
//reins_rate = reins_rate_base - atof(reins_prem_tbl(age_look, col_lookup));
//}
premium_re = reins_rate / normalization_factor;
premium_re = premium_re * (1. + underwriting_load) * (1. + prem_load);
}
int test_look_death_trf = trf_death_benefit_tbl(xstring(taarif), "death_benefit",1);
if(LOOKUP_FAILED != 2) {  // found index
double death_benefit;
death_benefit = trf_death_benefit_tbl(xstring(taarif), "death_benefit");
if(death_benefit == 0.) // factor_15 - without reinsurance
Abig = Abig + surv_per_np * sick_rate_np_dep * temp_fac * pow(1. +
int_rate_res_monthly, -i);
else
Abig = Abig + surv_per_np * (sick_rate_np_dep * temp_fac * (1 - ceded_pct) +
premium_re * ceded_pct) * pow(1. + int_rate_res_monthly, -i);
}
else
Abig = Abig + surv_per_np * (sick_rate_np_dep * temp_fac * (1 - ceded_pct) +
premium_re * ceded_pct) * pow(1. + int_rate_res_monthly, -i);
//Abig = Abig + surv_per_np * sick_rate_np_dep * temp_fac * pow(1. + int_rate_res_monthly, -
i);
a_dbl_dot = a_dbl_dot + surv_per_np * pow(1. + int_rate_res_monthly, -(i-1));
}
// close FOR loop
net_premium = Abig / a_dbl_dot;   // net monthly premium
}

