double set_ra_driver_component(xstring ra_type_mthd, int time, xstring mthly){
double add_mthly = 1.;
// Some of the component are monthly
if (mthly == "Y"){
add_mthly = 12.;
}
if(ra_type_mthd == "Claims"){
return claims_benefits(time);
//return claims_benefits_pv(time);
}else if(ra_type_mthd == "Surrender"){
return claims_surrender(time);
}else if(ra_type_mthd == "Expenses"){
return expense_total(time);
//return expense_pv(time);
}else if(ra_type_mthd == "SAR"){
double temp_surv = 0.;
if (cover_status == "PREM_PAY")
temp_surv = surv_prem_paying(time);
else
if(cover_status == "PUP")
temp_surv = surv_pup(time);
else
temp_surv = surv_claim(time);
return sum_ins_per_pol(time) * temp_surv / add_mthly;
}else if(ra_type_mthd == "Premium"){
return premium_total(time) * 12. / add_mthly;
    }else if(ra_type_mthd == "PremiumRe"){  // lapse risk
        if (pvfp_lapse_runoff(0)>= 0.) { // profitability test
double temp_calc = 0.;
if(rein_type == "YRT" && re_qx_key != "20"
&& surv_prem_paying(time - 1) + surv_pup(time - 1) > SMALL_DOUBLE)
temp_calc = surv_prem_paying(time - 1)
* premium_reins(time)
/ (surv_prem_paying(time - 1) + surv_pup(time - 1));
else
temp_calc = premium_reins(time);
return temp_calc * 12. / add_mthly;
    } // close profitability test
else return 0.;
}else if(ra_type_mthd == "ClaimsNet"){
return claims_benefits(time) - claims_benefits_rein(time);
//return claims_benefits_pv(time) - claims_benefits_rein_pv(time);
}else if(ra_type_mthd == "ClaimsRe"){
return claims_benefits_rein(time);
}else if(ra_type_mthd == "PVFPNet"|| ra_type_mthd == "PVFP"){
//if (pvfp_lapse_runoff(0)>= 0.){
//return dividend_pretax(time)
//+ reserve_increase(time) - inv_inc_total(time) -
rein_cost(time)
//- premium_reins(time) + claims_benefits_rein(time) +
commission_rein(time)
//+ rein_prof_comm(time);
return dividend_pretax(time) - rein_cost(time);
//}
//return 0.;
}else if(ra_type_mthd == "Recost"){
return - rein_cost(time) ;
//return - rein_cost(time)
//- premium_reins(time)
//+ claims_benefits_rein(time)
//+ commission_rein(time)
//+ rein_prof_comm(time);
}else if(ra_type_mthd == "SARNet"){
double temp_surv = 0.;
if (cover_status == "PREM_PAY")
temp_surv = surv_prem_paying(time);
else
if(cover_status == "PUP")
temp_surv = surv_pup(time);
else
temp_surv = surv_claim(time);
return (1 - ceded_pct) * sum_ins_per_pol(time) * temp_surv / add_mthly;
}else if(ra_type_mthd == "SARCeded"){
double temp_surv = 0.;
if (cover_status == "PREM_PAY")
temp_surv = surv_prem_paying(time);
else
if(cover_status == "PUP")
temp_surv = surv_pup(time);
else
temp_surv = surv_claim(time);
return ceded_pct * sum_ins_per_pol(time) * temp_surv / add_mthly;
}else{ // NA or Others
return 0.;
}
}

