treaty_index = 5; // no reinsurance
}
else if(date_index >= 200109) {
treaty_index = 4; // Munich Re - CARE / GOLDEN CARE
}
else if(date_index >= 199901) {
treaty_index = 3; // Munich Re - Zahav / Gil Zahav
}
else if(date_index >= 199106) {
treaty_index = 2; // Swiss Re - Siudit
