double ccf_calc_phi(int dur, int age, int claim_t, xstring term_rates_n, int franchisa, int
def_per){
int i = age;
int z = dur;
int ct = claim_t;
int j = 0.;
int k = 0.;
double a_ccf = 0.;
double surv_per = 0.;
double v_month = 1.;
//term_rates_phi_tbl = tables_path + "\\PHI\\" + termin_rates_name + "_" + term_rates_n + ".tbl";
term_rates_phi_tbl = rafm_input_parameters + "\\Morbidity\\" + termin_rates_name + "_" +
term_rates_n + ".tbl";
int r_num = atoi(term_rates_phi_tbl.high_index());
for (k=1+z;k<=ct+z;k++){
v_month = v_month * pow(1. + rdr_ccf[min(120,int((k-1+valn_month)/12.))], -1./12.);
v_monthly[k-z] = v_month;
}
for (j=1;j<=min(r_num,ct);j++){
if (j <= def_per)
surv_per = 0;
else if (j == def_per + 1)
surv_per = 1.;
else
surv_per = surv_per * (1. - term_rates_phi_tbl(j-1,i));
if (j >= def_per + 3)
franchisa = 1.;
a_ccf = a_ccf + surv_per * v_monthly[j] * franchisa;
}
return a_ccf;
}

