xstring last_word_str(xstring str)
{
int i = 1.; int j;
xstring my_string = str.strip(2);
xstring targ_str;
int cnt = my_string.length();
while(my_string(cnt - i,i).find(" ")>0){
targ_str = my_string(cnt - i,i);
i = i + 1;
}
  return targ_str;
}

