xstring adjust_capitlization(xstring user_str, xstring full_str)
{
xstring get_full_str = full_str;
xstring get_prt_str = user_str;
xstring correct_str;
int find_my_str;
int length_str = user_str.length();
for(int i = 0; i <= get_full_str.length(); i ++)
get_full_str[i] = toupper(get_full_str[i]);
for(int j = 0; j <= get_prt_str.length(); j ++)
get_prt_str[j] = toupper(get_prt_str[j]);
find_my_str = get_full_str.find(get_prt_str);
if(find_my_str != -1)
correct_str =  full_str(find_my_str,length_str);
else
correct_str = user_str;
return correct_str;
  }

double ccf_calc_f(int dur, int age, int claim_t){
int i = age;
int z = dur;
int ct = claim_t;
int j = 0.;
int k = 0.;
double a_ccf = 0.;
double surv_per = 0.;
double v_month = 1.;
for (k=1+z;k<=ct+z;k++){
v_month = v_month * pow(1. + rdr_ccf[min(120,int((k-1+valn_month)/12.))], -1./12.);
v_monthly[k-z] = v_month;
}
if(mort_mult == 1 && mort_mult_solvency == 1) {
for (j=1;j<=ct;j++){
if (j == 1)
surv_per = 1. - term_qx_rates_f_tbl(j,i) - term_rec_rates_f_tbl(j,i);
else
surv_per = surv_per * (1. - term_qx_rates_f_tbl(j,i) -
term_rec_rates_f_tbl(j,i));
a_ccf = a_ccf + surv_per * v_monthly[j];
}
}
else {
for (j=1;j<=ct;j++){
if (j == 1)
surv_per = 1. - (1-pow(1-(1-pow(1-term_qx_rates_f_tbl(j,i),12.)) * mort_mult
* mort_mult_solvency,1./12.)) - term_rec_rates_f_tbl(j,i);
else
surv_per = surv_per * (1. - (1-pow(1-(1-pow(1-term_qx_rates_f_tbl(j,i),12.))
* mort_mult * mort_mult_solvency,1./12.)) - term_rec_rates_f_tbl(j,i));
a_ccf = a_ccf + surv_per * v_monthly[j];
}
}
return a_ccf;
}

