double ccf_calc_phi(int dur, int age, int claim_t, xstring term_rates_n, int franchisa, int
def_per){
int i = age;
int z = dur;
int ct = claim_t;
int j = 0.;
int k = 0.;
double a_ccf = 0.;
double surv_per = 0.;
double v_month = 1.;
//term_rates_phi_tbl = tables_path + "\\PHI\\" + termin_rates_name + "_" + term_rates_n + ".tbl";
term_rates_phi_tbl = rafm_input_parameters + "\\Morbidity\\" + termin_rates_name + "_" +
term_rates_n + ".tbl";
int r_num = atoi(term_rates_phi_tbl.high_index());
for (k=1+z;k<=ct+z;k++){
v_month = v_month * pow(1. + rdr_ccf[min(120,int((k-1+valn_month)/12.))], -1./12.);
v_monthly[k-z] = v_month;
}
if(mort_mult == 1 && mort_mult_solvency ==1) {
for (j=1;j<=min(r_num,ct);j++){
if (j <= def_per)
surv_per = 0;
else if (j == def_per + 1)
surv_per = 1.;
else
surv_per = surv_per * (1. - term_rates_phi_tbl(j-1,i));
if (j >= def_per + 3)
franchisa = 1.;
a_ccf = a_ccf + surv_per * v_monthly[j] * franchisa;
}
}
return a_ccf;
}

xstring check_add_fields(xstring str_check)
{
xstring my_char = ",";
xstring part_str;
xstring fixed_str;
int length_str;
int my_indication;
my_indication = str_check.find(my_char);
//if there is only one additional field
if(my_indication == -1){
fixed_str = str_check.strip(2);
fixed_str = adjust_capitlization(fixed_str, str_prt_cf_all);
if(is_in_string(fixed_str,str_prt_cf_all) == false)
throw FatalError("ERROR: There is no CF field with the name:  " + fixed_str + ".  All
CF fields:" +
str_prt_cf_all);
}
//more than one additional field
while(my_indication != -1){
length_str = str_check.length();
my_indication = str_check.find(my_char);
part_str = str_check( 0 ,my_indication).strip(2);
str_check = str_check(my_indication + 1,length_str -(my_indication+1) );
part_str = adjust_capitlization(part_str, str_prt_cf_all);
fixed_str = fixed_str + "," + part_str;
fixed_str = fixed_str.strip(2);
if(is_in_string(part_str,str_prt_cf_all) == false)
throw FatalError("ERROR: There is no CF field with the name:  " + part_str + ".  All
CF fields:" +
str_prt_cf_all);
}
  return fixed_str;
}

double covg_units_fct(int time, xstring mthly){
