// Some of the component are monthly
if (mthly == "Y"){
add_mthly = 12.;
}
if (time < commence_nonneg_w || time > maturity_period_w)
return 0.0;
if (unit_type_mthd == "Premium"){ // old option at the end not in line with the regulator
return premium_reg_healthy(time) * 12
* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
}
if (unit_type_mthd == "SA"){ // not common option but indeed in use
//return surv_prem_paying(time) * (sum_ins_per_prem_pay_pol(time) +
sum_ins_waiver_after(max(1,time)))
//* cvgunits_adj_factor / add_mthly;
return surv_prem_paying(time) * (sum_ins_per_prem_pay_pol(time))
* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
}
int temp_def_per2 = min(6, max(1, deferred_period_w));
xstring aab_lookup = "aab" + xstring(temp_def_per2); // Additional Accident Benefit
xstring wowp_lookup = "wowp" + xstring(temp_def_per2); // Waiver of Waiting Period During
Hospitalization
double ancillary_bens = 0;
if(atid_batuach == "Y" && cover_status != "CLAIM"){
ancillary_bens = (ancillary_ben_tbl(max(20.,floor(age_exact_1(time))), aab_lookup)
+
ancillary_ben_tbl(max(20.,floor(age_exact_1(time))), wowp_lookup)) / 1000.; //Avoid from skipping
}
if(mitriya_pen == "Y") {
// when sa_pension is in data remove next line
// when sa_pension is in data - check if already multiplied by 0.75
// for now assume 50% of salary is in each category
double sa_pension = 0.5 * sum_ins_per_prem_pay_pol(time-1);
//double full_morb_sa = sum_ins_per_prem_pay_pol(time-1)
//+ sum_ins_waiver_after(time-1)
//- sa_pension;
double full_morb_sa = sum_ins_per_prem_pay_pol(time-1) - sa_pension;
double mitriya_morb_sa = sa_pension;
double morb_temp = (full_morb_sa + mitriya_morb_sa * mitriya_mult);
return (morb_temp * claims_factor_cvgunits(time) + ancillary_bens) *
surv_prem_paying(time-1)
* cvgunits_adj_factor / add_mthly * covunit_qne_mida;
