void set_net_premium() {
// NO mortality
double Abig = 0.;
// NO lapse
double a_dbl_dot = 0.;
   // YES interest
double ccf = 0.;
 // YES morbidity
double ccf1 = 0.;
double ccf2 = 0.;
double alfa = 0.;
int temp_def_per = min(12,max(1, deferred_period_w));
xstring heading = "V_" + xstring(max(3,temp_def_per)) + "_65";
net_premium = 0.;
int i;
int age_look;
if (age_exact_issue + elapsed_months/12. < 65) {
for (i=1;i<=(min(65,claim_end_age)-age_exact_issue)*12.;i++) {
age_look = floor(age_exact_issue +(i-1)/12.);
ccf = claims_factors_tbl(age_look, heading)/100./12.;
Abig = Abig + ccf * pow(1. + int_rate_res_monthly, -i);
a_dbl_dot = a_dbl_dot + pow(1. + int_rate_res_monthly, -(i-1));
}
net_premium = Abig / a_dbl_dot;   // net monthly premium
}
}

