//v1.11 new function
//"start" is time when claim occoured
// "duration" is from the end of the deferred period (ie point of first payment)
// (we may want to test whether having this as a temp table would be quicker)
double claim_link_factor ( int start, int duration)
{
if ( claim_link_code == "INFLATION") return 1.;
if ( claim_link_code == "INVEST" ) return investment_index (start + duration) /
investment_index(start);
//INV2INF  - investment link from the 25th payment
if(  duration < 24 ) return(1.);
// we are before the participating period
return (investment_index(start + duration) / investment_index( start + 23)); // from 25th
payment
}

double claims_benefits_first_a_mth(int time, int firstmthly){
if (time <= commence_nonneg_w || time > maturity_period_w)
return 0.0;
if(qod_hevra == 6) //Ignoring calc for waiver covers
if(bt_num == 11 || bt_num == 21 || bt_num == 31 || bt_num == 41 || bt_num == 51
|| bt_num == 61 || bt_num == 71 || bt_num == 81 || bt_num == 91 || bt_num == 101)
return 0.0;
double incid_fy_solvency = 1.;
if(time>=1 && time <= year_scenario_start * 12 + 12 && time > year_scenario_start * 12)
incid_fy_solvency = incidence_mult_solvency_fy;
// telem short term
double ims = 1.;
if (time > year_scenario_start * 12){
ims = incidence_mult_solvency;
}
if(loss_ratio_product == "Y" && cover_status == "PREM_PAY" && time <= firstmthly)
return loss_ratio * ims * incid_fy_solvency * premium_total(time) + ibnr(time-1);
// v3.16 added claims processing
// v3.38d moved res_claim_mult from dlr calc - needs to be for expereience also
// v4.0 replaced res_claim_mult with taluy and pmt_perc factors from data
// I left in res_claim_mult in order to give adjustment flexibility
if(cover_status == "CLAIM") {
if(claim_dur + time <= deferred_period_w) return 0. + ibnr(time-1);
if(basis_prefix_w == "V" && time <= firstmthly)
return res_claim_mult * surv_claim(time-1) * (taluy_perc * sa_claim +
taluy_pctw * sum_ins_waiver_after(time-1));
else{
double recovery_clm = 0.;
if(use_recovery_claim == "Y")
recovery_clm = claims_recoveries_after_claim_first_a_mth(time-
1,firstmthly) + claims_recover_to_pp_first_a_mth(time,firstmthly);
return res_claim_mult * surv_claim(time-1) * taluy_perc *
(sum_ins_per_prem_pay_pol(time-1) + sum_ins_waiver_after(time-1)) + ibnr(time-1) + recovery_clm;}
}
if(basis_prefix_w == "V" && time <= firstmthly)
return  0.08333333 * claims_factor(time) * incidence_multiplier
*((sum_ins_per_prem_pay_pol(time-1) +  sum_ins_waiver_after(time-1)) *
surv_prem_paying(time-1)) / 100.;
// v4.3.5 additional benefits for atid batuach
int temp_def_per2 = min(6, max(1, deferred_period_w));
xstring aab_lookup = "aab" + xstring(temp_def_per2); // Additional Accident Benefit
xstring wowp_lookup = "wowp" + xstring(temp_def_per2); // Waiver of Waiting Period During
Hospitalization
double ancillary_bens = 0;
if(atid_batuach == "Y") ancillary_bens =
(ancillary_ben_tbl(max(20.,floor(age_exact_1(time))),aab_lookup) +
ancillary_ben_tbl(max(20.,floor(age_exact_1(time))),wowp_lookup))/1000.; //Avoid from skipping
if (use_claim_cost_factors == "N"){
if (time<=1)
return 0.0 + ibnr(time-1);
if (commence_nonneg_w == 1.){
return ((sum_ins_waiver_after(time) * mitriya_mult + sum_ins_per_pol(time)) *
claims_payments_first_a_mth(time,firstmthly) + ancillary_bens * (sum_ins_per_pol(time-1) +
sum_ins_waiver_after(time-1)) * surv_healthy(time-1));}
return ((sum_ins_waiver_after(time-1) * mitriya_mult + sum_ins_per_pol(time-1)) *
claims_payments_first_a_mth(time-1,firstmthly) + ancillary_bens * (sum_ins_per_pol(time-1) +
sum_ins_waiver_after(time-1)) * surv_healthy(time-1));
}
// 25/01/2011 - hs
if(mitriya_pen == "Y" && time <= firstmthly) {
// when sa_pension is in data remove next line
// when sa_pension is in data - check if already multiplied by 0.75
// for now assume 50% of salary is in each category
double sa_pension = 0.5 * sum_ins_per_prem_pay_pol(time-1);
double full_morb_sa = sum_ins_per_prem_pay_pol(time-1)
+ sum_ins_waiver_after(time-1)
- sa_pension;
double mitriya_morb_sa = sa_pension;
double morb_temp = sick_rate_dep(time) * (full_morb_sa + mitriya_morb_sa *
mitriya_mult);
return (morb_temp * claims_factor(time) + ancillary_bens) * surv_prem_paying(time-1)
+ ibnr(time-1);
}
else if(time <= firstmthly) // old formula
return (sick_rate_dep(time) * claims_factor(time) * mitriya_mult + ancillary_bens) *
((sum_ins_per_prem_pay_pol(time-1) +  sum_ins_waiver_after(time-1)) *
surv_prem_paying(time-1)) + ibnr(time-1);
else
return 0.0;
}

double claims_payments_first_a_mth(int time, int firstmthly){
if (time <= commence_period_w || time > maturity_period_w)
return NO_AVG;
if (time < 0)
return 0.;
double clm_pyt_first_a_month = 0.;
for (int i=0; i >= time - firstmthly && i <= time; i++) {
clm_pyt_first_a_month += claims_payments_tt(time-i,i);
}
return clm_pyt_first_a_month;
}

double claims_recover_to_pp_first_a_mth(int time, int firstmthly){
if (time <= commence_nonneg_w || time > maturity_period_w)
return 0.0;
if (time <= 0)
return 0.;
if(taluy_perc == 1.)
return 0.0;
return (1 - taluy_perc) * clm_pp-> claims_benefits_first_a_mth(time, firstmthly);
}

double claims_recoveries_after_claim_first_a_mth(int time, int firstmthly){
if (time <= commence_nonneg_w || time > maturity_period_w)
return 0.0;
return res_claim_mult * claims_recovery_first_a_mth(time, firstmthly)
* taluy_perc *(sum_ins_per_pol(time) + sum_ins_waiver_after(time));
}

double claims_recovery_first_a_mth(int time, int firstmthly){
if (time <= commence_period_w || time > maturity_period_w)
return NO_AVG;
double clm_recov_first_a_month = 0.;
for (int i=0; i <= time && time <= firstmthly && i >= 0; i++) {
clm_recov_first_a_month += claims_recoveries_tt(time,i);
}
return clm_recov_first_a_month;
}

//v1.11 similar to dlr_factor, used to get values from dlr_dx table and interpolate if necessary
// r is start of claim time , c is duration
double dlr_dx_factor(int r, int c)
{
int yrly_factor = 24;
// PHI
if (c+1 <= yrly_factor)
 // dlr_dx_factor_tbl has monthly durations for first 60 months
return dlr_dx_factor_tbl(age_exact_1(r) , min(dlr_dx_factor_tbl.no_of_columns() ,
c+1));
int colindex = yrly_factor + xint ( (c + 1 -  yrly_factor) / 12.) +1;
// after yrly_factor months need to interpolate because table has factors at annual
intervals
double factor1 = dlr_dx_factor_tbl(age_exact_1(r) , min(dlr_dx_factor_tbl.no_of_columns() ,
colindex));
double factor2 = dlr_dx_factor_tbl(age_exact_1(r) , min(dlr_dx_factor_tbl.no_of_columns() ,
colindex+1));
double weight = (c+1.) / 12. - xint((c+1.) / 12.);
return factor1 * (1.-weight) + factor2 * weight ;
}

//v1.11 added to simplify coding of dlr_factor_phi
//"start" is claim start t, "duration" is duration of claim
double dlr_factor(int r, int c)
{
int yrly_factor = 24;
// PHI
if (c+1 <= yrly_factor)
 // dlr_factor_tbl has monthly durations for first 60 months
return dlr_factor_tbl(age_exact_1(r) , min(dlr_factor_tbl.no_of_columns() , c+1));
int colindex = yrly_factor + xint ( (c + 1 -  yrly_factor) / 12.) +1;
// after yrly_factor months need to interpolate because table has factors at annual
intervals
// assume claim started midpoint during age year, therfore average the DLR factors by age as
well (before only by duration)
double factor1 = (dlr_factor_tbl(age_exact_1(r) , min(dlr_factor_tbl.no_of_columns() ,
colindex)) +
     dlr_factor_tbl(age_exact_1(r) + 1,
min(dlr_factor_tbl.no_of_columns() , colindex)))/2.;
double factor2 = (dlr_factor_tbl(age_exact_1(r) , min(dlr_factor_tbl.no_of_columns() ,
colindex +1)) +
     dlr_factor_tbl(age_exact_1(r) + 1,
min(dlr_factor_tbl.no_of_columns() , colindex +1)))/2.;
double weight = (c+1.) / 12. - xint((c+1.) / 12.);
return factor1 * (1.-weight) + factor2 * weight ;
}

//v1.11 returns dlr factors for PHI
//may want to test this vs speed of a temp table
//start is time of claim start , duration is duration of claim
double dlr_factor_phi (int start, int duration)
{
if ( claim_end_age == phi_dlr_tables_age )
// can take directly from table
return dlr_factor(start,duration);
// a(x+t,y-x-t) = a(x+t,67-x-t) - dx(y)/dx(x+t)*a(y,67-y)
return dlr_factor(start, duration) -
dlr_dx_factor(start, maturity_period_w + 1 - start ) /
dlr_dx_factor(start,duration) *
dlr_factor(start, maturity_period_w + 1 - start );
}

