template < class T >
void tbl_to_array(xstring my_array, T my_tbl, xstring look_index ,double age, int l, bool full)
{
int i = 0; int j = 0; int ind_s  = 0;int k = 0;
int age_int = xint(age);
int my_cols = my_tbl.no_of_columns();
int my_rows = my_tbl.no_of_rows();
int arr_length = Variable(my_array).size();
xstring lookup_ind;
if(age < 0)
throw FatalError("age 0 means selection without age group, age > 0 means that the selection
is with age group, but age couldn't be <0 ");
if(age == 0){
for(k = l; k <= arr_length - 1 ; k ++){
if(k<=my_cols)
Variable(my_array).SetElementValue(k, my_tbl(look_index, k));
else if(full == true)
Variable(my_array).SetElementValue(k,
Variable(my_array).elementValueAsDouble(k-1));
}
return;
}
//Find the current age group
while(ind_s != -1. ){
lookup_ind = look_index + "_" + xstring(age_int - i);
my_tbl(lookup_ind, 1 ,1 );
if(LOOKUP_FAILED == 0)
ind_s = -1.;
else
i = i + 1;
if(age_int - i < 0){ //when after check all group bases there is no split by age
for(k = l; k <= arr_length - 1 ; k ++){
if(k<=my_cols)
Variable(my_array).SetElementValue(k, my_tbl(look_index, k));
else if(full == true)
Variable(my_array).SetElementValue(k,
Variable(my_array).elementValueAsDouble(k-1));
}
return;
}
}
j = 1.;
for(k = l; k <= my_cols ; k ++){
my_tbl( look_index + "_" + xstring(age_int + k - j), 1 ,1);
if(LOOKUP_FAILED == 0){
age_int = age_int + k - j;
j = k;
i = 0;
}
Variable(my_array).SetElementValue(k, my_tbl( look_index + "_" + xstring(age_int - i), k));
}
if(full == true)
for(k = my_cols + 1 ; k <= arr_length - 1 ; k ++)
Variable(my_array).SetElementValue(k, Variable(my_array).elementValueAsDouble(k-1));
}

void calc_omega_age(void) {
// Calculate omega age of mortality tables
omega_age_1 = death_rates_1_high_index + death_rates_1_no_of_columns - 1;
}

double calc_wol_ben_term (void) {
// Whole of life products require a benefit term to be set.
// A benefit term is calculated so that policies expire at the
// omega age.
double term;
term = 12 * (omega_age_1 - xint(age_exact_issue_1));
return term;
}

double monthly_rate(double annual_rate) {
return (pow(1. + annual_rate , 1. / 12.) - 1.);
}

