void set_premium_discount() {
// this is only run for fixed premium policies
int testmonth; int testmonth1;
hanacha_cov_1 = 0.; tosefet_cov_1 = 0.;
hanacha_pol_1 = 0.; tosefet_pol_1 = 0.;
int foundit; int i;
int months_from_base_pol = max(0, monthfrombase);  // for covers that start after the base policy
// percent of prem - cover level
foundit = 0;
i =0;
while (foundit == 0) {
i = i + 1;
testmonth = htprmmthc[i];
testmonth1 = htprmmthc[i+1];
if((abs(elapsed_months) >= testmonth  && abs(elapsed_months) < testmonth1 ) || i == 45) {
foundit = 1;
hanacha_cov_1 = htprmpctc[i];
}
}
// percent of prem - cover level
foundit = 0;
i =0;
while (foundit == 0) {
i = i + 1;
testmonth = tosprmmthc[i];
testmonth1 = tosprmmthc[i+1];
if((abs(elapsed_months) >= testmonth  && abs(elapsed_months) < testmonth1 ) || i == 45) {
foundit = 1;
tosefet_cov_1 = tosprmpctc[i];
}
}
// percent of prem - policy level - hevra account
foundit = 0;
i =0;
while (foundit == 0) {
i = i + 1;
testmonth = htprmmthph[i] - months_from_base_pol;
testmonth1 = htprmmthph[i+1] - months_from_base_pol;
if((abs(elapsed_months) >= testmonth  && abs(elapsed_months) < testmonth1 ) || i == 45) {
foundit = 1;
hanacha_pol_1 = hanacha_pol_1 + htprmpctph[i];
}
}
// percent of prem - policy level - sochen account
foundit = 0;
i =0;
while (foundit == 0) {
i = i + 1;
testmonth = htprmmthps[i] - months_from_base_pol;
testmonth1 = htprmmthps[i+1] - months_from_base_pol;
if((abs(elapsed_months) >= testmonth  && abs(elapsed_months) < testmonth1 ) || i == 45) {
foundit = 1;
hanacha_pol_1 = hanacha_pol_1 + htprmpctps[i];
}
}
// percent of prem - policy level
foundit = 0;
i =0;
while (foundit == 0) {
i = i + 1;
testmonth = tosprmmthp[i] - months_from_base_pol;
testmonth1 = tosprmmthp[i+1] - months_from_base_pol;
if((abs(elapsed_months) >= testmonth  && abs(elapsed_months) < testmonth1) || i == 45) {
foundit = 1;
tosefet_pol_1 = tosprmpctp[i];
}
}
if (system_orig == "HEALTH" && elapsed_months <= 0) {
hanacha_cov_1 = 0.; tosefet_cov_1 = 0.;
hanacha_pol_1 = 0.; tosefet_pol_1 = 0.;
}
//close function
}

void set_premium_gross (void) {
// gross up premiums from health system
set_premium_discount();
double discount_pol_total = hanacha_pol_1 - tosefet_pol_1;
if (system_orig == "LIFE") // for these the premium in data is net of cover level only
discount_pol_total = 0.;
double discount_cov_total = hanacha_cov_1 - tosefet_cov_1;
double discount_total = 0.;
if(qod_hevra == 10 || qod_hevra == 5)
discount_total = 1. - (1. - discount_pol_total) * (1. - discount_cov_total);
else
discount_total = (1. + discount_pol_total)* (1. + discount_cov_total) - 1.;
 // cover
discount is multiplicative with policy discount
if(discount_total >= 1.)
prem_curr = 0.;
else {
prem_curr = prem_curr / (1. - hatava_bank);
prem_curr = prem_curr / (1. - min(1. , discount_total));
// first remove discounts because
they are applied to extra premium as well
}
}//close function

