void validate_data(void) {
if (prem_term > benefit_term)
throw NonFatalError("Premium term can not be greater than benefit term.");
if (pv_period != 12)
throw NonFatalError("Template set up for monthly projections. Change the discount period in
the projection task.");
if (eq(projection_type,"Valn") && elapsed_months <= 0)
throw NonFatalError("For a valuation projection run, the policy must be in force, i.e.
elapsed_months positive.");
// Ensure frequencies given are factors of 12.
if ((12 % prem_freq != 0.0) ||
(prem_freq == 0 && policy_status != "PUP") || (prem_freq == 0 && prem_term >
elapsed_months)) { // premium frequency must be a multiple of 12 and must
   // not be zero whilst premiums are being paid.
throw NonFatalError("Premium frequency must be 1, 2, 3, 4, 6, or 12.");
}
if ((12 % surplus_distr_freq != 0.0) || (surplus_distr_freq == 0)){
throw NonFatalError("Surplus distribution frequency must be 1, 2, 3, 4, 6, or 12.");
}
if(date_birth < 190000)
throw NonFatalError("Invalid birth date");
if(sex1 == "A")
NonFatalError("Invalid sex");
// close function
}

