//return sum_insured_if_e(t) * (surr_rates_tbl(row_num, year) * (1. - cal_month(t)/12.) +
surr_rates_tbl(row_num,year + 1) * cal_month(t)/12.);

if (t < commence_period_w ||t > maturity_period_w)
return NO_AVG;
if (decrem == "N" && eq(model_name,"experience"))
return 1.0;
