if (t <= 0) // At start
return 1;
else
return surv(t-1) * surv_per(t);
}
if (eq(model_name,"Net_Prem")) {
if (t == commence_period_w) // At start
return 1;
else
return surv(t-1) * surv_per(t);
}
// t < 0
if (isRebaseClone)
throw FatalError ("Cannot calculate survivorship in rebased clone for t < 0");
return 0;

if (t < commence_period_w || t<=0)
return 1.;
if (t > maturity_period_w + 1)
return NO_AVG;
return surv_ann_pizz_new(t-1) * (1. - min(1., death_rate_ann_res(t) + lapse_ann_res_pizz_new(t)));

if (t < commence_period_w || t<=0)
return 1.;
if (t > maturity_period_w + 1)
return NO_AVG;
return surv_ann_pizz_old(t-1) * (1. - min(1., death_rate_ann_res(t) + lapse_ann_res_pizz_old(t)));

if (t < commence_period_w || t<=0)
return 1.;
if (t > maturity_period_w + 1)
return NO_AVG;
return surv_ann_tag_new(t-1) * (1. - min(1., death_rate_ann_res(t) + lapse_ann_res_tag_new(t)));

if (t < commence_period_w || t<=0)
