return surv_ann_tag_old(t-1) * (1. - min(1., death_rate_ann_res(t) + lapse_ann_res_tag_old(t)));

if ((t <= commence_period_w) || (t > maturity_period_w))
return NO_AVG;
if (t > 0 && fabs(surv(t-1)) < SMALL_DOUBLE)
return NO_AVG;
if (decrem == "N"&& eq(model_name,"experience"))
return 1.0;
// Assume deaths are uniformly distributed in period
return pow ((1 - death_rate(t)), 0.5);

if (t <= commence_period_w || t > maturity_period_w)
return NO_AVG;
if (decrem == "N"&& eq(model_name,"experience"))
return 1.0;
// if (t <= 0)
//
return 1.0;
if(surv(t-1) < SMALL_DOUBLE) return 0.;
return (1. - death_rate(t)) * (1. - lapse_rate(t));

if (t < commence_period_w || t > maturity_period_w)
return 0.0;
if(eq(after_tax_ev,"Y"))
return profit_tax(t) * tax_rates[max(0 , xint(cal_year(t)) - valn_year)];
return 0.;

if (t < commence_period_w  || t > maturity_period_w)
return 0.0;
//Correcting discount timing from v_month(t) to v_month(t+1) so Res - BEL = VIF
return (tax(t+1) + tax_pv(t+1)) * v_month(t+1);

int temp_t = 0;
//int ev_time_adj = 0;
