//temp_t = max((t - 1 - ev_time_adj),1)/12. + 1;
temp_t = max((t - 1 - interest_shift),1)/12. + 1;
if (use_fixed_rate == "Y")
return  pow(1. + int_margin_trad, -1./12.);
else
return  pow(1. + rdr[temp_t] - int_margin + int_margin_trad, -1./12.);

if (t < commence_period_w || t >= maturity_period_w)
