void set_correct_surr_values() {
int i;
xstring do_not_process = "N";
int final_vector_spot = 1;
double final_vector_value = 1.;
xstring check_no_more = "N";
if(( fc_lapse==1||fc_claims==1||fc_hatavot==1|| fc_amalot==1 )&& qod_chgsts == "PP_PUP") {
double fact_temp = 1.;
if (prod_class == "END")
fact_temp = 0.75;
if (prod_class == "GIMLA")
fact_temp = 0.95;
if (prod_class == "YTRON")
fact_temp = 0.75;
if (prod_class == "ZAPAK")
fact_temp = 0.85;
if (prod_class == "MATAN")
fact_temp = 1.;
if (prod_class == "PUR")
fact_temp = 1.;
for (i=0; i <= 99; i++)
surr_rates[i] = surr_rates[i] * fact_temp;
}
for (i=1; i <= 99; i++){
if (surr_rates[i] > 1. || eq(prod_class,"MATAN") && eq(cover_status, "PREM_PAY"))
do_not_process = "Y";
if (surr_rates[i] <= surr_rates[i-1] && eq(check_no_more,"N")){
final_vector_spot = i-1;
final_vector_value = surr_rates[i-1];
check_no_more = "Y";
} // close if
} // close for_loop
double remaining_years = (maturity_period_w / 12.) - final_vector_spot;
double remaining_surr_value = 1. - final_vector_value;
double addtl_per_year;
if (remaining_years > 0)
addtl_per_year = remaining_surr_value / remaining_years;
else
addtl_per_year = 0.;
for (i=0; i <= 99; i++){
surr_rates_new[i] = surr_rates[i];
if (eq(do_not_process,"N") && (i > final_vector_spot)) {
surr_rates_new[i] = min(surr_rates_new[i-1] + addtl_per_year,1.);
}
} // close for_loop
} // close function

