}else if(ra_type_mthd == "Surrender"){
return claims_surr(time);
// Just for Annuity
//}else if(ra_type_mthd == "AnnReserve"){
//return reserve(time) / add_mthly;
//}else if(ra_type_mthd == "PVFP"){
//if(pvfp_lapse_runoff(min(0,maturity_period_w))> 0.){
////double temp1; double temp2;
////temp1 = embedded_value_e(time);
//
