////if (main->trad_record > 1 && main->annuity_record > 1 && cover_num >
SMALL_DOUBLE)
////ev_ann_temp = "ev_ann_" + xstring(cover_num);
////else
////ev_ann_temp = "ev_ann";
////temp2 = main->Column(ev_ann_temp).Value(time);
//
////return temp1 + temp2 - rein_cost_pv(time);
//return profit(time) - rein_cost(time);
//}
//return 0.0;
}else if(ra_type_mthd == "Expenses"){
return expense_total(time);
//return expense_pv(time);
}else if(ra_type_mthd == "SAR"){
return sum_insured_if_b(time) / add_mthly;
}else if(ra_type_mthd == "Premium"){
//return premium_total(time);
//return premium_pv(time);
return premium_total(time) * 12. / add_mthly;
}else if(ra_type_mthd == "PVFPNet"|| ra_type_mthd == "PVFP"){
//if (pvfp_lapse_runoff(0)>= 0.){
return profit(time);
//}
//return 0.;
}else if(ra_type_mthd == "ClaimsNet"){
return claims_death(time) - claims_death_reins(time);
//return claims_death_pv(time) - claims_death_reins_pv(time);
}else if(ra_type_mthd == "SARNet"){
return (1 - re_pct) * sum_insured_if_b(time) / add_mthly;
}else if(ra_type_mthd == "Recost"){
return -rein_cost(time);
}else if(ra_type_mthd == "ClaimsRe"){
return claims_death_reins(time);
