void validate_data(void) {
int ret_age = age_exact_issue + benefit_term / 12;
if (elapsed_months != 0 && ! eq(projection_type,"Experience"))
throw NonFatalError("If non valuation projection type, then elapsed months must be zero.");
if (prem_term > benefit_term)
throw NonFatalError("Premium term can not be greater than benefit term.");
if (pv_period != 12)
throw NonFatalError("Template set up for monthly projections. Change the discount period in
the projection task.");
// check minimum age of mortality tables
int min_age_1 = death_rates_1_low_index;
//min_age_1 = max(0, min_age_1 + death_rates_1_no_of_columns - 1);
min_age_1 = max(0, min_age_1 - 1);
if (age_exact_issue < min_age_1)
throw NonFatalError ("Policy number " + pol_number + ": Issue age of life 1 is less than the
minimum age of the " + model_name + " mortality table");
if (eq(projection_type,"Experience") && elapsed_months <= 0)
throw NonFatalError("For a valuation projection run, the policy must be in force, i.e.
elapsed_months positive.");
// Ensure frequencies given are factors of 12.
if (prem_freq > 0)
if (12 % prem_freq != 0.0)
{ // premium frequency must be a multiple of 12 and must
   // not be zero whilst premiums are being paid.
throw NonFatalError("Premium frequency must be 0,1, 2, 3, 4, 6, or 12.");
}
if ((12 % surplus_distr_freq != 0.0) || (surplus_distr_freq == 0)){
throw NonFatalError("Surplus distribution frequency must be 1, 2, 3, 4, 6, or 12.");
}
if (! inlist(prod_class,"WOL,END,PUR,ZAPAK,MATAN,YTRON,HALF,GIMLA"))
throw NonFatalError("Unknown prod_class for policy number: " + pol_number);
if (sum_ins_curr == 0)
throw NonFatalError("Sum Insured is zero for policy number " + pol_number);
//if (surr_rates[0] == 0.)
//
throw NonFatalError("No Surrender values for policy number " + pol_number);
// close function
}

